const tasks=[{title:'案内資料の見出しを整理する',minutes:30},{title:'Pythonの基本を1つ試す',minutes:20},{title:'今日の気づきをひと言残す',minutes:5}];
const list=document.getElementById('tasks');
function updateCount(){document.getElementById('count').textContent=`${tasks.filter(t=>t.done).length} / ${tasks.length} 完了`;}
function render(){list.replaceChildren();tasks.forEach(task=>{const row=document.createElement('label');row.className='task task-line';const box=document.createElement('input');box.type='checkbox';box.checked=!!task.done;const copy=document.createElement('span'),name=document.createElement('strong'),time=document.createElement('small');name.textContent=task.title;time.textContent=`目安 ${task.minutes}分`;copy.append(name,time);row.append(box,copy);row.classList.toggle('complete',box.checked);box.addEventListener('change',()=>{task.done=box.checked;row.classList.toggle('complete',box.checked);updateCount()});list.append(row)});updateCount()}
document.getElementById('add-task').addEventListener('submit',e=>{e.preventDefault();const title=document.getElementById('task-title').value.trim();if(!title)return;tasks.push({title,minutes:Number(document.getElementById('task-minutes').value)});render();e.target.reset()});
document.getElementById('notes').addEventListener('submit',e=>{e.preventDefault();document.getElementById('note-status').textContent='この画面にメモを残しました。外部への送信・保存は行いません。'});
document.getElementById('reset').addEventListener('click',()=>location.reload());
function route(){const id=['today','week','experience','goals'].includes(location.hash.slice(1))?location.hash.slice(1):'today';document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('h1').textContent=document.querySelector('nav a.active').textContent;}
window.addEventListener('hashchange',route);render();route();
